import "@lo-tek/interfaces/connection-status.css"
import { lt } from "@lo-tek/interfaces/react"
import {
  defineLtConnectionStatus,
  reportFailure,
  reportSuccess,
} from "@lo-tek/interfaces/connection-status"
import "@lo-tek/interfaces/tokens.css"

defineLtConnectionStatus()

export function Connection() {
  return <lt-connection-status {...lt.connectionStatus()} />
}

export async function saveRoute(body: BodyInit) {
  const connection = document.querySelector("lt-connection-status")
  if (!connection) throw new Error("element not found")
  let response: Response | undefined
  try {
    response = await fetch("/api/routes", { method: "POST", body })
  } catch {}
  // No answer, or a gateway whose server is gone, is a lost connection.
  // The save does not wait for the report.
  if (response && ![502, 503, 504].includes(response.status)) reportSuccess(connection)
  else reportFailure(connection)
  return response
}

import kotlinx.html.*
import no.lotek.*
import no.lotek.html.lt
import no.lotek.html.ltConnectionStatus

fun FlowContent.connection() {
    ltConnectionStatus {
        lt(Lt.connectionStatus())
        // `retrying`: the request got no answer. `error`: an answer of 400 or
        // more; 502, 503 and 504 come from a gateway whose server is gone,
        // any other is a server that is there. A patch: the stream is alive.
        attributes["data-on:datastar-fetch__document"] =
            "evt.detail.type === 'retrying' || [502, 503, 504].includes(+evt.detail.argsRaw.status) ? el.reportFailure() : (evt.detail.type === 'error' || evt.detail.type.startsWith('datastar-patch')) && el.reportSuccess()"
    }
}

// Once for the whole app, in the page template. Not once per component.
head { link(rel = "stylesheet", href = LotekWebJar.CSS) }
body {
    connection()
    script(type = "module") { unsafe { +"import { defineLt } from \"${LotekWebJar.REGISTER}\"; defineLt()" } }
    // Datastar itself, once for the whole app, after the registration:
    // module scripts run in the order they stand, so no request goes out
    // before the web components exist.
    script(type = "module", src = "https://cdn.jsdelivr.net/gh/starfederation/datastar@v1.0.4/bundles/datastar.js") {}
}

