import { useRef } from "react"
import { lt } from "@lo-tek/interfaces/react"

import "@lo-tek/interfaces/tokens.css"
import "@lo-tek/interfaces/dialog.css"
import "@lo-tek/interfaces/button.css"

export function CancelJob({ cancel }: { cancel: () => void }) {
  const dialog = useRef<HTMLDialogElement>(null)
  const box = lt.dialog({ titleId: "confirm-title" })

  return (
    <>
      <button
        {...lt.button({ variant: "danger" })}
        type="button"
        onClick={() => {
          if (!dialog.current) return
          // Escape and close() without a value leave the previous value in place.
          dialog.current.returnValue = ""
          dialog.current.showModal()
        }}
      >
        Cancel the job
      </button>

      <dialog
        {...box.dialog}
        ref={dialog}
        onClose={(e) => {
          if (e.currentTarget.returnValue === "cancel") cancel()
        }}
      >
        <h2 {...box.title}>Cancel job 222-0481?</h2>
        <div {...box.body}>
          <p>The crew keeps the advance. This cannot be undone.</p>
        </div>
        <form method="dialog" {...box.footer}>
          <button {...lt.button({ variant: "secondary" })} value="keep">Keep the job</button>
          <button {...lt.button({ variant: "danger" })} value="cancel">Cancel the job</button>
        </form>
      </dialog>
    </>
  )
}

import kotlinx.html.*
import no.lotek.*
import no.lotek.html.lt
import no.lotek.html.ltDialog

fun FlowContent.cancelJob(open: Boolean = true) {
    val box = Lt.dialog(titleId = "confirm-title", open = open)
    ltDialog {
        lt(box.host)
        id = "confirm"
        dialog {
            lt(box.dialog)
            // Escape is a close request, reported with `cancel`, and it
            // keeps the job. A close the server makes gives no `cancel`.
            attributes["data-on:cancel"] = "@post('/jobs/222-0481/keep')"
            h2 { lt(box.title); +"Cancel job 222-0481?" }
            div {
                lt(box.body)
                p { +"The crew keeps the advance. This cannot be undone." }
            }
            form {
                lt(box.footer)
                attributes["method"] = "dialog"
                button {
                    lt(Lt.button(variant = ButtonVariant.SECONDARY))
                    value = "keep"
                    attributes["data-on:click"] = "@post('/jobs/222-0481/keep')"
                    +"Keep the job"
                }
                button {
                    lt(Lt.button(variant = ButtonVariant.DANGER))
                    value = "cancel"
                    attributes["data-on:click"] = "@post('/jobs/222-0481/cancel')"
                    +"Cancel the job"
                }
            }
        }
    }
}

// Once for the whole app, in the page template. Not once per component.
head { link(rel = "stylesheet", href = LotekWebJar.CSS) }
body {
    // The page that asks the user to confirm, so the dialog is sent open. On
    // a page where it waits for a request, call cancelJob(open = false).
    cancelJob()
    script(type = "module") { unsafe { +"import { defineLt } from \"${LotekWebJar.REGISTER}\"; defineLt()" } }
    // Datastar itself, once for the whole app, after the registration:
    // module scripts run in the order they stand, so no request goes out
    // before the web components exist.
    script(type = "module", src = "https://cdn.jsdelivr.net/gh/starfederation/datastar@v1.0.4/bundles/datastar.js") {}
}

