import "@lo-tek/interfaces/session-timeout.css"
import { useEffect, useId, useRef } from "react"
import { lt } from "@lo-tek/interfaces/react"
import { defineLtSessionTimeout } from "@lo-tek/interfaces/session-timeout"
import "@lo-tek/interfaces/tokens.css"

defineLtSessionTimeout()

export function SessionWarning() {
  const ref = useRef<HTMLElement>(null)
  const session = lt.sessionTimeout({ titleId: useId(), warnAt: 1500, expiresAt: 1800 })

  useEffect(() => {
    const element = ref.current
    if (!element) return

    const expired = () => { location.href = "/log-in?reason=expired" }
    const extend = async () => {
      // No answer leaves the user here with what is not saved.
      const answer = await fetch("/api/extend-session", { method: "POST" })
        .catch(() => null)
      // A session the server says is gone, or a redirect to its log-in.
      if (answer && (answer.redirected || [401, 403].includes(answer.status)))
        expired()
    }

    element.addEventListener("session-extend", extend)
    element.addEventListener("session-expired", expired)
    return () => {
      element.removeEventListener("session-extend", extend)
      element.removeEventListener("session-expired", expired)
    }
  }, [])

  return (
    <lt-session-timeout ref={ref} {...session.host}>
      <dialog {...session.dialog}>
        <h2 {...session.title}>Your session is ending</h2>
        <p {...session.text}>
          Your session on the Lattice ends in <span {...session.count} />. Unsaved routes will be lost.
        </p>
        <span {...session.live} />
        <form {...session.actions}>
          <button {...session.extend}>Stay connected</button>
          {/* Posts to the logout on the server, which ends the session there. */}
          <button {...session.logout} formMethod="post" formAction="/log-out">Log out</button>
        </form>
      </dialog>
    </lt-session-timeout>
  )
}

import kotlinx.html.*
import no.lotek.*
import no.lotek.html.lt
import no.lotek.html.ltSessionTimeout

fun FlowContent.sessionWarning() {
    val session = Lt.sessionTimeout(titleId = "session-title", warnAt = 1500, expiresAt = 1800)
    ltSessionTimeout {
        lt(session.host)
        attributes["data-on:session-extend"] = "@post('/api/extend-session')"
        attributes["data-on:session-expired"] = "window.location = '/log-in?reason=expired'"
        dialog {
            lt(session.dialog)
            h2 { lt(session.title); +"Your session is ending" }
            p {
                lt(session.text)
                +"Your session on the Lattice ends in "
                span { lt(session.count) }
                +". Unsaved routes will be lost."
            }
            span { lt(session.live) }
            form {
                lt(session.actions)
                attributes["method"] = "dialog"
                button { lt(Lt.button(), session.extend); +"Stay connected" }
                button {
                    lt(Lt.button(variant = ButtonVariant.SECONDARY), session.logout)
                    // Logging out is a post to the server, which ends the session.
                    formMethod = ButtonFormMethod.post
                    formAction = "/log-out"
                    +"Log out"
                }
            }
        }
    }
}

// Once for the whole app, in the page template. Not once per component.
head { link(rel = "stylesheet", href = LotekWebJar.CSS) }
body {
    sessionWarning()
    script(type = "module") { unsafe { +"import { defineLt } from \"${LotekWebJar.REGISTER}\"; defineLt()" } }
    // Datastar itself, once for the whole app, after the registration:
    // module scripts run in the order they stand, so no request goes out
    // before the web components exist.
    script(type = "module", src = "https://cdn.jsdelivr.net/gh/starfederation/datastar@v1.0.4/bundles/datastar.js") {}
}

