import { useState } from "react"
import { lt } from "@lo-tek/interfaces/react"

export function AutoRenewSwitch({ initial }: { initial: boolean }) {
  const [on, setOn] = useState(initial)
  const [saving, setSaving] = useState(false)
  const [status, setStatus] = useState("")

  async function changed(value: boolean) {
    // While a save is in progress, the switch stays where the state says.
    // `disabled` would block it the same way, but take focus from it.
    if (saving) return

    // Flip at once, so the switch does not lag behind the finger.
    setOn(value)
    setSaving(true)
    setStatus("")

    try {
      const response = await fetch("/api/subscription", {
        method: "PUT",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ autoRenew: value }),
      })
      // A redirect, as to the log-in page when the session has run out, is
      // followed to a page that is ok, but nothing was saved.
      if (!response.ok || response.redirected) throw new Error(response.statusText)
      setStatus(value ? "Auto-renew is on." : "Auto-renew is off. Your walls expire with the subscription.")
    } catch {
      // Back to where it was. The switch promised something it did not keep.
      setOn(!value)
      setStatus("Could not save. Try again.")
    } finally {
      setSaving(false)
    }
  }

  return (
    <>
      <div className={lt.switch.row}>
        <input
          {...lt.switch()}
          id="auto-renew"
          checked={on}
          onChange={(e) => changed(e.currentTarget.checked)}
        />
        <label {...lt.label()} htmlFor="auto-renew">Auto-renew</label>
      </div>
      <p {...lt.helpText()} role="status">{status}</p>
    </>
  )
}

import kotlinx.html.*
import no.lotek.*
import no.lotek.html.lt

fun FlowContent.autoRenew(on: Boolean = false) {
    // autocomplete="off" stands on the form, since HTML does not allow it on
    // a checkbox. Without it Firefox keeps the state from before a reload
    // over the one the server rendered, until Datastar has loaded.
    form {
        autoComplete = false
        div {
            lt(Lt.switch.row)
            attributes["data-signals"] = "{renew: $on, status: ''}"
            input {
                lt(Lt.`switch`())
                id = "auto-renew"
                checked = on
                attributes["data-bind:renew"] = ""
                attributes["data-on:change"] = "@put('/api/subscription')"
            }
            label { lt(Lt.label()); htmlFor = "auto-renew"; +"Auto-renew" }
        }
    }
    // `\$status` is Datastar's signal, not a Kotlin template.
    p { lt(Lt.helpText()); attributes["role"] = "status"; attributes["data-text"] = "\$status" }
}

// Once for the whole app, in the page template. The switch is CSS alone,
// so there is no web component to register.
head { link(rel = "stylesheet", href = LotekWebJar.CSS) }
body {
    autoRenew()
    // Datastar itself, once for the whole app. Without it the `data-`
    // attributes in the recipe do nothing.
    script(type = "module", src = "https://cdn.jsdelivr.net/gh/starfederation/datastar@v1.0.4/bundles/datastar.js") {}
}

