data class Fault(val field: String, val message: String)

// The faults for what was submitted. Empty when the job can be ordered.
fun faultsIn(fixer: String): List<Fault> =
    if (fixer.contains("@")) emptyList()
    else listOf(Fault("fixer", "Enter the fixer's address with an @"))

fun FlowContent.orderForm(fixer: String = "", faults: List<Fault> = emptyList()) {
    val summary = Lt.errorSummary(count = faults.size, id = "errors")
    val field = Lt.field(id = "fixer", invalid = faults.any { it.field == "fixer" })
    form(action = "/jobs", method = FormMethod.post) {
        // The server checks the address. The browser's own check of
        // type="email" would stop the submission before it got there.
        attributes["novalidate"] = ""
        ltErrorSummary {
            lt(summary.host)
            h2 {
                lt(summary.title)
                if (faults.isNotEmpty()) +(if (faults.size == 1) "The form has one error" else "The form has ${faults.size} errors")
            }
            ul {
                lt(Lt.list())
                for (fault in faults) li { a(href = "#${fault.field}") { +fault.message } }
            }
        }
        label { lt(field.label); +"Fixer's address" }
        input {
            lt(Lt.input(type = InputType.EMAIL), field.control)
            name = "fixer"
            if (fixer.isNotEmpty()) value = fixer
        }
        button { lt(Lt.button()); +"Order the job" }
    }
}

fun HTML.jobsPage(ordered: Boolean = false, content: FlowContent.() -> Unit) {
    attributes["lang"] = "en"
    head {
        title("Order a job")
        link(rel = "stylesheet", href = LotekWebJar.CSS)
    }
    body {
        if (ordered) div { lt(Lt.alert(color = AlertColor.SUCCESS)); p { +"The job has been ordered." } }
        content()
        script(type = "module") { unsafe { +"import { defineLt } from \"${LotekWebJar.REGISTER}\"; defineLt()" } }
    }
}

fun Application.jobs() {
    routing {
        staticResources("/webjars", "META-INF/resources/webjars")
        get("/jobs") {
            val ordered = call.request.queryParameters.contains("ordered")
            call.respondHtml { jobsPage(ordered) { orderForm() } }
        }
        post("/jobs") {
            val fixer = call.receiveParameters()["fixer"].orEmpty().trim()
            val faults = faultsIn(fixer)
            if (faults.isEmpty()) {
                // Save the job here.
                call.respondRedirect("/jobs?ordered")
            } else {
                call.respondHtml(HttpStatusCode.UnprocessableEntity) { jobsPage { orderForm(fixer, faults) } }
            }
        }
    }
}

